use std::fs;
use std::path::Path;

fn main() {
    let icons_dir = Path::new("icons");
    let _ = fs::create_dir_all(icons_dir);

    write_b64(icons_dir.join("32x32.png"), "");
    write_b64(icons_dir.join("128x128.png"), "");
    write_b64(icons_dir.join("128x128@2x.png"), "");
    write_b64(icons_dir.join("icon.ico"), "PLACEHOLDER_ICO_WILL_BE_REPLACED");
    write_b64(icons_dir.join("icon.icns"), "PLACEHOLDER_ICO_WILL_BE_REPLACED");

    tauri_build::build()
}

fn write_b64(path: impl AsRef<Path>, b64: &str) {
    use base64::Engine;
    if let Ok(bytes) = base64::engine::general_purpose::STANDARD.decode(b64) {
        let _ = fs::write(path, bytes);
    }
}
